func uniquePaths(m int, n int) int {
    dp := make([]int, n)
    for j := range dp {
        dp[j] = 1
    }
    for i := 1; i < m; i++ {
        for j := 1; j < n; j++ {
            dp[j] += dp[j-1]
        }
    }
    return dp[n-1]
}

func uniquePaths(m int, n int) int {
    // C(m+n-2, m-1)
    res := 1
    for i := 0; i < m-1; i++ {
        res = res * (m + n - 2 - i) / (i + 1)
    }
    return res
}
